--
-- Name: fn_evaluate_fantasy_team(integer, integer); Type: FUNCTION; Schema: public; Owner: myuser
--

CREATE FUNCTION public.fn_evaluate_fantasy_team(p_team_id integer, p_gameweek_id integer) RETURNS TABLE(team_name_out character varying, formation_out character varying, total_squad_value numeric, budget_remaining numeric, starting_xi_points integer, avg_points_per_player numeric, captain_name text, health_rating text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_team_rec   RECORD;
    v_sel_rec    RECORD;
    v_total_val  NUMERIC(8,1) := 0;
    v_total_pts  INT          := 0;
    v_xi_count   INT          := 0;
    v_captain    TEXT         := 'Unknown';
    v_avg        NUMERIC;
    v_health     TEXT;

    -- Explicit cursor: all 15 squad players for this team / gameweek
    cur_squad CURSOR FOR
        SELECT
            fts.is_captain,
            fts.is_on_bench,
            fts.points_scored,
            p.price,
            p.first_name || ' ' || p.last_name AS player_name,
            pos.short_name                      AS pos_short
        FROM   FANTASY_TEAM_SELECTION fts
        JOIN   PLAYER   p   ON fts.player_id  = p.player_id
        JOIN   POSITION pos ON p.position_id  = pos.position_id
        WHERE  fts.team_id    = p_team_id
          AND  fts.gameweek_id = p_gameweek_id
        ORDER  BY fts.is_on_bench, pos.position_id;
BEGIN
    -- Implicit cursor: validate the fantasy team exists
    SELECT ft.team_name, ft.budget_remaining, ft.formation
    INTO   v_team_rec
    FROM   FANTASY_TEAM ft
    WHERE  ft.team_id = p_team_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Fantasy team with ID % does not exist.', p_team_id;
    END IF;

    -- Iterate the squad using the explicit cursor
    OPEN cur_squad;
    LOOP
        FETCH cur_squad INTO v_sel_rec;
        EXIT WHEN NOT FOUND;

        -- Every player (including bench) counts toward squad value
        v_total_val := v_total_val + v_sel_rec.price;

        -- Only starting XI contributes to points average
        IF v_sel_rec.is_on_bench = 0 THEN
            v_total_pts := v_total_pts + COALESCE(v_sel_rec.points_scored, 0);
            v_xi_count  := v_xi_count + 1;
        END IF;

        -- Identify captain
        IF v_sel_rec.is_captain = 1 THEN
            v_captain := v_sel_rec.player_name || ' (' || v_sel_rec.pos_short || ')';
        END IF;
    END LOOP;
    CLOSE cur_squad;

    -- Guard: no starting XI found
    IF v_xi_count = 0 THEN
        RAISE EXCEPTION
            'No starting XI selection found for team % in gameweek %.',
            p_team_id, p_gameweek_id;
    END IF;

    v_avg := ROUND(v_total_pts::NUMERIC / v_xi_count, 2);

    -- Classify team health based on average points per starting player
    IF v_avg >= 8 THEN
        v_health := 'Excellent';
    ELSIF v_avg >= 5 THEN
        v_health := 'Good';
    ELSIF v_avg >= 3 THEN
        v_health := 'Average';
    ELSE
        v_health := 'Poor';
    END IF;

    RETURN QUERY
        SELECT
            v_team_rec.team_name::VARCHAR(100),
            v_team_rec.formation::VARCHAR(10),
            v_total_val,
            v_team_rec.budget_remaining,
            v_total_pts,
            v_avg,
            v_captain,
            v_health;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION
            'fn_evaluate_fantasy_team error (team %, GW %): %',
            p_team_id, p_gameweek_id, SQLERRM;
END;
$$;


ALTER FUNCTION public.fn_evaluate_fantasy_team(p_team_id integer, p_gameweek_id integer) OWNER TO myuser;

--
-- Name: fn_get_player_season_stats(integer); Type: FUNCTION; Schema: public; Owner: myuser
--

CREATE FUNCTION public.fn_get_player_season_stats(p_player_id integer) RETURNS refcursor
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cursor refcursor := 'player_stats_cursor';
    v_player RECORD;
BEGIN
    -- Implicit cursor: fetch player details for validation
    SELECT player_id,
           first_name || ' ' || last_name AS full_name,
           price,
           total_points
    INTO   v_player
    FROM   PLAYER
    WHERE  player_id = p_player_id;

    -- Branch: abort if player not found
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Player with ID % does not exist in the database.', p_player_id;
    END IF;

    RAISE NOTICE 'Opening season stats cursor for: % (ID: %, Price: £%m, Total pts: %)',
        v_player.full_name, v_player.player_id, v_player.price, v_player.total_points;

    -- Open the named REF CURSOR with a multi-join query
    OPEN v_cursor FOR
        SELECT
            gw.season_year,
            gw.gameweek_number,
            m.match_date,
            ht.team_name    AS home_team,
            at_t.team_name  AS away_team,
            m.home_score,
            m.away_score,
            pgs.minutes_played,
            pgs.goals_scored,
            pgs.assists,
            pgs.clean_sheet,
            pgs.yellow_cards,
            pgs.red_cards,
            pgs.saves,
            pgs.bonus_points,
            pgs.total_points AS gw_points
        FROM   PLAYER_GAMEWEEK_STATS pgs
        JOIN   MATCH       m    ON pgs.match_id    = m.match_id
        JOIN   GAMEWEEK    gw   ON pgs.gameweek_id = gw.gameweek_id
        JOIN   REAL_TEAM   ht   ON m.home_team_id  = ht.real_team_id
        JOIN   REAL_TEAM   at_t ON m.away_team_id  = at_t.real_team_id
        WHERE  pgs.player_id = p_player_id
        ORDER  BY gw.season_year, gw.gameweek_number;

    RETURN v_cursor;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'fn_get_player_season_stats failed for player ID %: %',
            p_player_id, SQLERRM;
END;
$$;


ALTER FUNCTION public.fn_get_player_season_stats(p_player_id integer) OWNER TO myuser;

--
-- Name: pr_process_gameweek_points(integer); Type: PROCEDURE; Schema: public; Owner: myuser
--

CREATE PROCEDURE public.pr_process_gameweek_points(IN p_gameweek_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_sel_rec      RECORD;
    v_team_rec     RECORD;
    v_stat_pts     INT;
    v_final_pts    INT;
    v_gw_exists    INT;
    v_standing_id  INT;
    v_new_id       INT;

    -- Explicit cursor: all selections for this gameweek
    cur_sel CURSOR FOR
        SELECT
            fts.selection_id,
            fts.team_id,
            fts.player_id,
            fts.is_captain,
            fts.is_on_bench
        FROM   FANTASY_TEAM_SELECTION fts
        WHERE  fts.gameweek_id = p_gameweek_id
        ORDER  BY fts.team_id, fts.is_on_bench;
BEGIN
    -- Implicit cursor: validate gameweek exists
    SELECT COUNT(*) INTO v_gw_exists
    FROM   GAMEWEEK
    WHERE  gameweek_id = p_gameweek_id;

    IF v_gw_exists = 0 THEN
        RAISE EXCEPTION 'Gameweek % does not exist.', p_gameweek_id;
    END IF;

    RAISE NOTICE 'Processing points for gameweek %...', p_gameweek_id;

    -- ─── Step 1: update points_scored for every selection ────────────────
    OPEN cur_sel;
    LOOP
        FETCH cur_sel INTO v_sel_rec;
        EXIT WHEN NOT FOUND;

        IF v_sel_rec.is_on_bench = 1 THEN
            -- Bench players earn 0 fantasy points
            v_final_pts := 0;
        ELSE
            -- Implicit cursor: look up real stats for this player / gameweek
            SELECT COALESCE(pgs.total_points, 0)
            INTO   v_stat_pts
            FROM   PLAYER_GAMEWEEK_STATS pgs
            WHERE  pgs.player_id   = v_sel_rec.player_id
              AND  pgs.gameweek_id = p_gameweek_id
            LIMIT  1;

            IF NOT FOUND THEN
                v_stat_pts := 0;  -- player had no real-world stats (absent)
            END IF;

            -- Captain earns double points
            IF v_sel_rec.is_captain = 1 THEN
                v_final_pts := v_stat_pts * 2;
            ELSE
                v_final_pts := v_stat_pts;
            END IF;
        END IF;

        -- DML 1: write points back to selection row
        UPDATE FANTASY_TEAM_SELECTION
        SET    points_scored = v_final_pts
        WHERE  selection_id  = v_sel_rec.selection_id;

    END LOOP;
    CLOSE cur_sel;

    -- ─── Step 2: roll up into FANTASY_TEAM.total_points ──────────────────
    -- DML 2: accumulate this gameweek's total onto the team's season total
    UPDATE FANTASY_TEAM ft
    SET    total_points = ft.total_points + (
               SELECT COALESCE(SUM(fts.points_scored), 0)
               FROM   FANTASY_TEAM_SELECTION fts
               WHERE  fts.team_id    = ft.team_id
                 AND  fts.gameweek_id = p_gameweek_id
           )
    WHERE  ft.team_id IN (
               SELECT DISTINCT team_id
               FROM   FANTASY_TEAM_SELECTION
               WHERE  gameweek_id = p_gameweek_id
           );

    -- ─── Step 3: snapshot league standings ───────────────────────────────
    -- FOR implicit cursor loop: rank each team within its league
    FOR v_team_rec IN
        SELECT
            ft.team_id,
            ft.league_id,
            ft.total_points,
            RANK() OVER (
                PARTITION BY ft.league_id
                ORDER BY     ft.total_points DESC
            )::INT AS rank_in_league
        FROM FANTASY_TEAM ft
        WHERE ft.team_id IN (
            SELECT DISTINCT team_id
            FROM   FANTASY_TEAM_SELECTION
            WHERE  gameweek_id = p_gameweek_id
        )
    LOOP
        -- Check for existing snapshot (re-run guard)
        SELECT standing_id INTO v_standing_id
        FROM   LEAGUE_STANDING
        WHERE  league_id   = v_team_rec.league_id
          AND  team_id     = v_team_rec.team_id
          AND  gameweek_id = p_gameweek_id;

        IF FOUND THEN
            -- DML 3a: update existing snapshot
            UPDATE LEAGUE_STANDING
            SET    points = v_team_rec.total_points,
                   rank   = v_team_rec.rank_in_league
            WHERE  standing_id = v_standing_id;
        ELSE
            -- DML 3b: insert new snapshot (safe sequential ID)
            SELECT COALESCE(MAX(standing_id), 0) + 1
            INTO   v_new_id
            FROM   LEAGUE_STANDING;

                 v_team_rec.total_points,
                 v_team_rec.rank_in_league,
                 v_team_rec.league_id,
                 v_team_rec.team_id,
                 p_gameweek_id);
        END IF;
    END LOOP;

    RAISE NOTICE 'Gameweek % processing complete.', p_gameweek_id;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'pr_process_gameweek_points failed for GW %: %',
            p_gameweek_id, SQLERRM;
END;
$$;


ALTER PROCEDURE public.pr_process_gameweek_points(IN p_gameweek_id integer) OWNER TO myuser;

--
-- Name: pr_update_player_prices(); Type: PROCEDURE; Schema: public; Owner: myuser
--

CREATE PROCEDURE public.pr_update_player_prices()
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_player      RECORD;
    v_new_price   NUMERIC(5,1);
    v_total       INT := 0;
    v_updated     INT := 0;
    v_raised      INT := 0;
    v_dropped     INT := 0;

    -- Explicit cursor: all players ordered for deterministic processing
    cur_players CURSOR FOR
        SELECT
            player_id,
            first_name || ' ' || last_name AS full_name,
            price,
            total_points,
            selected_by_percent,
            position_id
        FROM   PLAYER
        ORDER  BY player_id;
BEGIN
    -- Implicit cursor: confirm there are players to process
    SELECT COUNT(*) INTO v_total FROM PLAYER;

    IF v_total = 0 THEN
        RAISE EXCEPTION 'No players found in the database — nothing to update.';
    END IF;

    RAISE NOTICE 'Starting price update for % players...', v_total;

    OPEN cur_players;
    LOOP
        FETCH cur_players INTO v_player;
        EXIT WHEN NOT FOUND;

        v_new_price := v_player.price;  -- default: no change

        -- Price-rise: strong performance + high demand
        IF v_player.total_points > 100
           AND COALESCE(v_player.selected_by_percent, 0) > 20
        THEN
            v_new_price := LEAST(v_player.price + 0.1, 20.0);
            v_raised    := v_raised + 1;

        -- Price-drop: poor performance + low demand
        ELSIF v_player.total_points < 30
              AND COALESCE(v_player.selected_by_percent, 0) < 5
        THEN
            v_new_price := GREATEST(v_player.price - 0.1, 0.1);
            v_dropped   := v_dropped + 1;
        END IF;

        -- Only write to DB if price actually changes
        IF v_new_price <> v_player.price THEN
            UPDATE PLAYER
            SET    previous_price = v_player.price,
                   price          = v_new_price
            WHERE  player_id = v_player.player_id;

            v_updated := v_updated + 1;

            RAISE NOTICE 'Player %-% (ID %): £%m → £%m',
                v_player.full_name,
                CASE WHEN v_new_price > v_player.price THEN '▲' ELSE '▼' END,
                v_player.player_id,
                v_player.price,
                v_new_price;
        END IF;

    END LOOP;
    CLOSE cur_players;

    RAISE NOTICE '--- Price update complete ---';
    RAISE NOTICE 'Players checked: %  |  Updated: %  |  Raised: %  |  Dropped: %',
        v_total, v_updated, v_raised, v_dropped;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'pr_update_player_prices failed: %', SQLERRM;
END;
$$;


ALTER PROCEDURE public.pr_update_player_prices() OWNER TO myuser;

--
-- Name: trg_fn_log_price_change(); Type: FUNCTION; Schema: public; Owner: myuser
--

CREATE FUNCTION public.trg_fn_log_price_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_diff      NUMERIC(5,1);
    v_direction TEXT;
BEGIN
    -- Hard guardrail: reject prices outside the allowed fantasy range
    IF NEW.price < 0.1 OR NEW.price > 20.0 THEN
        RAISE EXCEPTION
            'Invalid price % for player % % (ID %): must be between 0.1 and 20.0.',
            NEW.price, NEW.first_name, NEW.last_name, NEW.player_id;
    END IF;

    -- Only act when the price value actually changed
    IF NEW.price IS DISTINCT FROM OLD.price THEN
        v_diff := ROUND(NEW.price - OLD.price, 1);

        IF v_diff > 0 THEN
            v_direction := 'RISE';
        ELSE
            v_direction := 'FALL';
        END IF;

        -- Persist the old price for audit purposes
        NEW.previous_price := OLD.price;

        RAISE NOTICE 'Price % — % % (ID %): £%m → £%m (change: %)',
            v_direction,
            NEW.first_name, NEW.last_name, NEW.player_id,
            OLD.price, NEW.price, v_diff;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_fn_log_price_change() OWNER TO myuser;

--
-- Name: trg_fn_validate_transfer(); Type: FUNCTION; Schema: public; Owner: myuser
--

CREATE FUNCTION public.trg_fn_validate_transfer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_budget      NUMERIC(6,1);
    v_team_name   VARCHAR(100);
    v_player_in   TEXT;
    v_player_out  TEXT;
BEGIN
    -- Implicit cursor 1: fetch team budget
    SELECT ft.budget_remaining, ft.team_name
    INTO   v_budget, v_team_name
    FROM   FANTASY_TEAM ft
    WHERE  ft.team_id = NEW.team_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer rejected: fantasy team ID % not found.', NEW.team_id;
    END IF;

    -- Implicit cursor 2: fetch incoming player name
    SELECT first_name || ' ' || last_name
    INTO   v_player_in
    FROM   PLAYER
    WHERE  player_id = NEW.player_in_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer rejected: incoming player ID % not found.', NEW.player_in_id;
    END IF;

    -- Implicit cursor 3: fetch outgoing player name (for the notice message)
    SELECT first_name || ' ' || last_name
    INTO   v_player_out
    FROM   PLAYER
    WHERE  player_id = NEW.player_out_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer rejected: outgoing player ID % not found.', NEW.player_out_id;
    END IF;

    -- Budget check: block the transfer if the team cannot afford it
    IF v_budget < NEW.price_paid THEN
        RAISE EXCEPTION
            'Transfer rejected: team "%" has insufficient budget. '
            'Available: £%m  |  Required: £%m  |  Shortfall: £%m',
            v_team_name,
            v_budget,
            NEW.price_paid,
            (NEW.price_paid - v_budget);
    END IF;

    -- DML: deduct cost from budget and accumulate season spend
    UPDATE FANTASY_TEAM
    SET    budget_remaining     = budget_remaining - NEW.price_paid,
           total_transfers_cost = COALESCE(total_transfers_cost, 0) + NEW.price_paid
    WHERE  team_id = NEW.team_id;

    RAISE NOTICE
        'Transfer approved [team "%"]: OUT % → IN % for £%m  (budget left: £%m)',
        v_team_name,
        v_player_out,
        v_player_in,
        NEW.price_paid,
        (v_budget - NEW.price_paid);

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_fn_validate_transfer() OWNER TO myuser;

