    player_id integer NOT NULL,
    first_name character varying(50) NOT NULL,
    last_name character varying(50) NOT NULL,
    nationality character varying(50),
    price numeric(5,1) NOT NULL,
    total_points integer DEFAULT 0,
    selected_by_percent numeric(5,2),
    birth_date date,
    contract_start_date date,
    real_team_id integer NOT NULL,
    position_id integer NOT NULL,
    person_id character varying(50),
    previous_price numeric(5,1),
    CONSTRAINT player_price_check CHECK (((price > (0)::numeric) AND (price <= (20)::numeric))),
    CONSTRAINT player_selected_by_percent_check CHECK (((selected_by_percent >= (0)::numeric) AND (selected_by_percent <= (100)::numeric)))
);


ALTER TABLE public.player OWNER TO myuser;

--
-- Name: player_gameweek_stats; Type: TABLE; Schema: public; Owner: myuser
--

CREATE TABLE public.player_gameweek_stats (
    stat_id integer NOT NULL,
    minutes_played integer DEFAULT 0,
    goals_scored integer DEFAULT 0,
    assists integer DEFAULT 0,
    clean_sheet integer DEFAULT 0,
    yellow_cards integer DEFAULT 0,
    red_cards integer DEFAULT 0,
    saves integer DEFAULT 0,
    bonus_points integer DEFAULT 0,
    total_points integer DEFAULT 0,
    player_id integer NOT NULL,
    match_id integer NOT NULL,
    gameweek_id integer NOT NULL,
    CONSTRAINT player_gameweek_stats_assists_check CHECK ((assists >= 0)),
    CONSTRAINT player_gameweek_stats_bonus_points_check CHECK (((bonus_points >= 0) AND (bonus_points <= 3))),
    CONSTRAINT player_gameweek_stats_clean_sheet_check CHECK ((clean_sheet = ANY (ARRAY[0, 1]))),
    CONSTRAINT player_gameweek_stats_goals_scored_check CHECK ((goals_scored >= 0)),
    CONSTRAINT player_gameweek_stats_minutes_played_check CHECK (((minutes_played >= 0) AND (minutes_played <= 120))),
    CONSTRAINT player_gameweek_stats_red_cards_check CHECK ((red_cards = ANY (ARRAY[0, 1]))),
    CONSTRAINT player_gameweek_stats_saves_check CHECK ((saves >= 0)),
    CONSTRAINT player_gameweek_stats_yellow_cards_check CHECK (((yellow_cards >= 0) AND (yellow_cards <= 2)))
);


ALTER TABLE public.player_gameweek_stats OWNER TO myuser;

