    country character varying(50) NOT NULL,
    founded_year integer,
    CONSTRAINT real_team_founded_year_check CHECK (((founded_year > 1800) AND (founded_year <= 2024)))
);


ALTER TABLE public.real_team OWNER TO myuser;

