    transfer_date date NOT NULL,
    team_id integer NOT NULL,
    player_out_id integer NOT NULL,
    player_in_id integer NOT NULL,
    gameweek_id integer NOT NULL,
    CONSTRAINT transfer_check CHECK ((player_out_id <> player_in_id)),
    CONSTRAINT transfer_price_paid_check CHECK ((price_paid > (0)::numeric))
);


ALTER TABLE public.transfer OWNER TO myuser;

--
-- Name: users; Type: TABLE; Schema: public; Owner: myuser
--

CREATE TABLE public.users (
    user_id integer NOT NULL,
    username character varying(50) NOT NULL,
    email character varying(100) NOT NULL,
    password_hash character varying(255) NOT NULL,
    country character varying(50),
    registration_date date NOT NULL,
    birth_date date,
    CONSTRAINT chk_users_age CHECK ((EXTRACT(year FROM age((CURRENT_DATE)::timestamp with time zone, (birth_date)::timestamp with time zone)) >= (18)::numeric)),
    CONSTRAINT chk_users_country CHECK (((country)::text <> 'Iran'::text)),
    CONSTRAINT users_check CHECK ((birth_date < registration_date))
);


ALTER TABLE public.users OWNER TO myuser;

--
-- Name: v_fantasy_player_profile; Type: VIEW; Schema: public; Owner: myuser
--

CREATE VIEW public.v_fantasy_player_profile AS
 SELECT p.player_id,
    (((p.first_name)::text || ' '::text) || (p.last_name)::text) AS player_name,
    pos.position_name,
    pos.short_name AS pos_short,
    rt.team_name AS club_team,
    rt.country AS club_country,
    p.price,
    p.total_points,
    p.selected_by_percent,
    p.nationality
   FROM ((public.player p
     JOIN public.real_team rt ON ((p.real_team_id = rt.real_team_id)))
     JOIN public."position" pos ON ((p.position_id = pos.position_id)));


ALTER VIEW public.v_fantasy_player_profile OWNER TO myuser;

--
-- Name: v_world_cup_match_details; Type: VIEW; Schema: public; Owner: myuser
--

CREATE VIEW public.v_world_cup_match_details AS
 SELECT im.matchid,
    im.tournament,
    im.stage,
    im.matchdate,
    home_t.countryname AS home_team,
    guest_t.countryname AS guest_team,
    s.name AS stadium_name,
    s.city AS stadium_city,
    s.country AS stadium_country,
    s.capacity AS stadium_capacity,
    im.matchtime
   FROM (((public.intl_match im
     JOIN public.intl_team home_t ON (((im.hometeamcode)::text = (home_t.teamcode)::text)))
     JOIN public.intl_team guest_t ON (((im.guestteamcode)::text = (guest_t.teamcode)::text)))
     JOIN public.stadium s ON (((im.stadiumid)::text = (s.stadiumid)::text)));


ALTER VIEW public.v_world_cup_match_details OWNER TO myuser;

